<template id="detail-template"><div class="detail-row"><div class="row-number"></div><div class="detail-fields"><label>Description *<input data-name="item_desc" required></label><label>Unit<input data-name="item_unit" placeholder="pcs, set"></label><label>Serial no.<input data-name="item_serial_no"></label><label>Remarks<input data-name="remarks"></label></div><button type="button" class="remove-row">×</button></div></template>
<script>document.addEventListener('DOMContentLoaded',()=>{const list=document.querySelector('#detail-list'), tpl=document.querySelector('#detail-template'); const renumber=()=>[...list.children].forEach((row,i)=>{row.querySelector('.row-number').textContent=i+1; row.querySelectorAll('[data-name]').forEach(el=>el.name=`details[${i}][${el.dataset.name}]`)}); document.querySelector('#add-detail').onclick=()=>{list.append(tpl.content.cloneNode(true));renumber()}; list.addEventListener('click',e=>{if(e.target.classList.contains('remove-row')&&list.children.length>1){e.target.closest('.detail-row').remove();renumber()}});renumber()});</script>
